int bin_search(int *arr, int len, int target) {
    int l = 0;
    int r = len - 1;
    int mid = (l + r) / 2;
    while(l <= r) {
        //Found:
        if(arr[mid] == target) return mid;
        //Num is too big:
        else if(arr[mid] > target) r = mid; 
        //Num is too small:
        else l = mid + 1;
        //Reset mid with our new left and right pointers.
